content('red', ('Questions and answers', 'Perguntas e respostas', 'Preguntas y respuestas'), ('The five questions every workshop asks in the first hour.', 'As cinco perguntas que todo workshop faz na primeira hora.', 'Las cinco preguntas que todo workshop hace en la primera hora.'),
    C.defs([('Does a hook replace permission rules?', 'No. Rules are declarative and cheap; a hook reads the payload. Use rules for tool kinds and a hook for decisions that need context.'),
            ('What happens on a timeout?', 'The tool runs. Every timeout fails open, even for policy hooks; only a crash on preToolUse denies.'),
            ('Can the developer turn it off?', 'User, repository and inline hooks honor disableAllHooks. Policy hooks and managed settings do not.'),
            ('Where does the deny reason go?', 'Back to the model as the next instruction, so it changes the next attempt instead of triggering a retry.'),
            ('Does the cloud agent run my hooks?', 'Only .github/hooks on the default branch, bash entries only; no user files, no policy hooks, no plugins.')]),
    N('Q and A rows: the question badge is the accent, the answer is plain. Good for the slide before a break.', 'Linhas de pergunta e resposta: o selo da pergunta é o accent, a resposta é texto simples. Bom para o slide antes da pausa.', 'Filas de pregunta y respuesta: el sello de la pregunta es el accent, la respuesta es texto simple. Bueno para el slide antes de la pausa.'))

content('red', ('Glossary', 'Glossário', 'Glosario'), ('Sixteen terms, numbered, in four colors.', 'Dezesseis termos, numerados, em quatro cores.', 'Dieciséis términos, numerados, en cuatro colores.'),
    C.glossary([('Hook', 'A command, HTTP call or prompt the runtime executes at a lifecycle event, JSON in and JSON out.'), ('Event', 'One of fourteen moments in a session, from sessionStart to sessionEnd.'), ('preToolUse', 'The only event that can deny a tool call, with allow, deny or ask.'), ('agentStop', 'Fires when the agent wants to end the turn; block forces another one.'),
                ('Matcher', 'A regex anchored as ^(?:PATTERN)$ against the tool or agent name.'), ('PascalCase alias', 'Stop, PreToolUse: names compatible with Claude and VS Code.'), ('Fail-closed', 'A crashed preToolUse hook denies; a timeout never does.'), ('Policy hook', 'Admin-installed in policy.d; loads first, cannot be disabled.'),
                ('disableAllHooks', 'The documented switch for user, repo and inline hooks.'), ('additionalContext', 'Text injected into the session, capped at 10 KB.'), ('stop_hook_active', 'True on the forced turn after a block.'), ('http hook', 'A POST to an https endpoint with allowedEnvVars headers.'),
                ('Permission rule', 'Declarative allow, deny or ask by tool kind and argument pattern.'), ('Sandbox bypass', 'A tool call that is never pre-approved.'), ('Managed settings', 'JSON managed by MDM or server; most restrictive wins.'), ('Safe output', 'The Agentic Workflows equivalent of a guardrail.')]),
    N('Glossary: four columns, numeral in the corner, colored top border. Sixteen is the maximum that still reads at 720p.', 'Glossário: quatro colunas, numeral no canto, borda superior colorida. Dezesseis é o máximo que ainda se lê em 720p.', 'Glosario: cuatro columnas, numeral en la esquina, borde superior de color. Dieciséis es el máximo que aún se lee en 720p.'))

